import random
random.seed(91)

def f(x):
  return (x -7)**2 + 4;

# random.uniform is assigning random position to values
# at a specific range for example (0, 14) is range
positions = [random.uniform(0, 14) for _ in range(6)]

velocities= [0 for _ in range(6)]

# [:] creating and duplicating a new list
# but also preserving the positions or data of the previous list
pbest_pos = positions[:]

# min() extracting minimum value from all personal best positions
gbest_pos = min(pbest_pos, key=f)
w ,c1, c2 = 0.6, 1.5, 1.5
iterations = 50

for it in range(iterations):
  for i in range(6):
    # Generate two randomn numbers
    r1, r2 = random.random(), random.random()

    velocities[i] = (
            # Keep some of the particle's previous velocity.
            w * velocities[i]
            # Moving toward personal best
            + c1 * r1 * (pbest_pos[i] - positions[i])
            # Moving toward global best
            + c2 * r2 * (gbest_pos - positions[i])
        )

        # Update position xnew​=xold​+v
    positions[i] = positions[i] + velocities[i]
    if f(positions[i]) < f(pbest_pos[i]):
      pbest_pos[i] = positions[i]
  gbest_pos = min(pbest_pos, key=f)
print("Swarm converged near x =", gbest_pos)